for lang, entries in pairs(deathStatueNotifies) do
    if notifyConfig[lang] then
        for key, data in pairs(entries) do
            notifyConfig[lang][key] = {
                ["title"] = data.title,
                ["message"] = data.message,
                ["type"] = data.type,
                ["duration"] = data.duration,
            }
        end
    end
end
